const toastListeners=new Set();
let toastSequence=0;
function notify(message,variant){
 const text=String(message?.message||message||'').trim();
 if(!text)return;
 const errorPattern=/تعذر|فشل|خطأ|غير موجود|لا يمكن|لا يوجد|غير متاح|غير متوفر|غير كاف|تجاوز|أكبر من|أقل من|مطلوب|يجب|يرجى|لا بد|مكرر|غير صحيح|غير صالح|انتهت|رفض|حدث خطأ|error|failed|invalid|insufficient|not found|cannot|could not|unable|denied/i;
 const successPattern=/تم |بنجاح|نجح|اكتمل|حُفظ|تمت /i;
 const kind=variant||(errorPattern.test(text)?'error':successPattern.test(text)?'success':'info');
 const item={id:++toastSequence,text,kind,duration:kind==='error'?7000:kind==='warning'?6000:kind==='success'?4000:3000};
 for(const fn of toastListeners)fn(item);
}
function SmartToastHost(){
 const [items,setItems]=useState([]);
 const timers=useRef(new Map());
 const [dialogTarget,setDialogTarget]=useState(null);
 useEffect(()=>{
  const current=()=>{const dialogs=document.querySelectorAll('dialog[open]');return dialogs.length?dialogs[dialogs.length-1]:null};
  let last=current();setDialogTarget(last);
  const observer=new MutationObserver(()=>{const next=current();if(next!==last){last=next;setDialogTarget(next)}});
  observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
  return()=>observer.disconnect();
 },[]);
 const dismiss=id=>{clearTimeout(timers.current.get(id));timers.current.delete(id);setItems(list=>list.filter(x=>x.id!==id))};
 useEffect(()=>{
  const handler=item=>setItems(list=>[...list.slice(-2),item]);
  toastListeners.add(handler);
  return()=>{toastListeners.delete(handler);for(const timer of timers.current.values())clearTimeout(timer);timers.current.clear()};
 },[]);
 useEffect(()=>{
  for(const item of items)if(!timers.current.has(item.id))timers.current.set(item.id,setTimeout(()=>dismiss(item.id),item.duration));
  for(const [id,timer] of timers.current)if(!items.some(x=>x.id===id)){clearTimeout(timer);timers.current.delete(id)}
 },[items]);
 const target=dialogTarget?.isConnected&&dialogTarget.open?dialogTarget:document.body;
 const view=<div className="smartToastStack" dir="rtl" aria-live="polite" aria-atomic="false">{items.map(item=><div className={`smartToast smartToast--${item.kind}`} role={item.kind==='error'?'alert':'status'} key={item.id}><span className="smartToastIcon" aria-hidden="true">{item.kind==='success'?'✓':item.kind==='error'?'!':item.kind==='warning'?'⚠':'i'}</span><span className="smartToastMessage">{item.text}</span><button type="button" className="smartToastClose" aria-label="إغلاق الإشعار" onClick={()=>dismiss(item.id)}>×</button><span className="smartToastProgress" style={{animationDuration:`${item.duration}ms`}}/></div>)}</div>;
 return createPortal(view,target);
}

const money=v=>{const n=Number(v);return Number.isFinite(n)?n.toLocaleString('ar-SY',{maximumFractionDigits:2}):'0'};
const localDateKey=d=>{const x=d instanceof Date?d:new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const localDateTime=d=>{if(!d)return '—';try{const dt=new Date(d);const tz=Intl.DateTimeFormat().resolvedOptions().timeZone||undefined;const locale=navigator.language||'ar-SY';return new Intl.DateTimeFormat(locale,{dateStyle:'medium',timeStyle:'short',hour12:false,timeZone:tz}).format(dt)}catch{return new Date(d).toLocaleString()}};
function useUsbBarcodeCapture(enabled,onCode){
 const callbackRef=useRef(onCode); const bufferRef=useRef(''); const lastRef=useRef(0); const timerRef=useRef(null);
 useEffect(()=>{callbackRef.current=onCode},[onCode]);
 useEffect(()=>{
  if(!enabled)return;
  const reset=()=>{bufferRef.current='';lastRef.current=0;if(timerRef.current){clearTimeout(timerRef.current);timerRef.current=null}};
  const onKey=e=>{
   const target=e.target; const tag=(target?.tagName||'').toUpperCase();
   const isEditable=tag==='TEXTAREA'||target?.isContentEditable;
   const now=Date.now();
   if(e.key==='Enter'){
    const rapid=now-lastRef.current<=220;
    const targetValue=tag==='INPUT'&&typeof target.value==='string'?target.value.trim():'';
    const code=(bufferRef.current||targetValue).trim();
    if(code.length>=4 && (rapid || bufferRef.current.length>=4)){
      if(!isEditable){e.preventDefault()}
      reset();
      callbackRef.current?.(code);
    }
    return;
   }
   if(typeof e.key!=='string'||e.key.length!==1)return;
   if(tag==='TEXTAREA'||target?.isContentEditable)return;
   if(now-lastRef.current>90)bufferRef.current=e.key; else bufferRef.current+=e.key;
   lastRef.current=now;
   if(timerRef.current)clearTimeout(timerRef.current);
   timerRef.current=setTimeout(reset,260);
  };
  window.addEventListener('keydown',onKey,true);
  return()=>{window.removeEventListener('keydown',onKey,true);reset()};
 },[enabled]);
}

