class AppErrorBoundary extends React.Component {
  constructor(props){super(props);this.state={error:null}}
  static getDerivedStateFromError(error){return {error}}
  componentDidCatch(error,info){console.error('Pharmacy UI error',error,info)}
  render(){
    if(this.state.error) return <div className="center" dir="rtl"><h1>حدث خطأ في واجهة الصيدلية</h1><p>السلة أو إحدى الواجهات واجهت خطأ غير متوقع.</p><button className="primary" onClick={()=>this.setState({error:null})}>إعادة المحاولة</button><small style={{display:'block',marginTop:12,opacity:.7}}>{this.state.error?.message||'Unknown error'}</small></div>;
    return this.props.children;
  }
}

