 const load=async()=>{const collected=[];const pageSize=500;for(let offset=0;offset<100000;offset+=pageSize){const {data,error}=await supabase.rpc('admin_get_inventory').range(offset,offset+pageSize-1);if(error)throw error;const page=data||[];collected.push(...page);if(page.length<pageSize)break;}const all=collected.map(x=>({id:x.batch_id,product_id:x.product_id,expiry_date:x.expiry_date,quantity:x.quantity,purchase_price:x.purchase_price,received_date:x.received_date,products:{name:x.name,barcode:x.barcode,active_ingredient:x.active_ingredient,reorder_level:x.reorder_level,sale_price:x.sale_price,purchase_price:x.product_purchase_price,manufacturer:x.manufacturer,strength:x.strength,dosage_form:x.dosage_form,parts_per_unit:x.parts_per_unit}}));setAllRows(all);setRows(filterRows(all,q))};
