 const top=(data?.items||[]).slice(0,6); const topMax=Math.max(1,...top.map(x=>Number(x.net_sales||0)));
 const avg=Number(sm.sales_count||0)?Number(sm.sales||0)/Number(sm.sales_count):0;
 const margin=Number(sm.margin||0); const best=top[0]?.product_name||'لا يوجد صنف مسجل';
