 const load=async()=>{setBusy(true);try{const {data,error}=await supabase.rpc('admin_customer_profiles');if(error)throw error;setRows(data||[])}catch(e){notify(e.message||'تعذر تحميل العملاء')}finally{setBusy(false)}};
